const D = { hue: 300, energy: .6, speed: 1, density: .55, scale: 1, warp: .5, braid: .45, x: .5, y: .5, style: 'silk', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const TAU = 6.28318530718;
const clp = (v,a,b)=> v<a?a:(v>b?b:v);
const sd = (P.seed|0);
const hsh = i => { const s = Math.sin(i*127.1 + sd*311.7)*43758.5453; return s - Math.floor(s); };

// --- per-style discipline: ground tone, blend, ribbon width ---
const style = P.style;
let addMode=true, wMul=1, gH=286, gS=50, gB=21, fadeA=9;
if (style==='aurora'){ addMode=true; wMul=1.75; gH=236; gS=64; gB=12; fadeA=8; }
else if (style==='copper'){ addMode=true; wMul=0.55; gH=20; gS=46; gB=7; fadeA=11; }
else if (style==='watercolor'){ addMode=false; wMul=2.15; gH=42; gS=14; gB=88; fadeA=7; }
else if (style==='blueprint'){ addMode=true; wMul=0.5; gH=214; gS=82; gB=28; fadeA=10; }

// --- size-keyed feedback fabric buffer (opaque ground, own HSB space) ---
const scl = Math.min(1, 820/Math.max(width,height));
const BW = Math.max(2, Math.round(width*scl)), BH = Math.max(2, Math.round(height*scl));
const key = width+'x'+height;
if (!S.buf || S.key !== key){
  if (S.buf && S.buf.remove) S.buf.remove();
  S.buf = createGraphics(BW, BH); S.buf.pixelDensity(1);
  S.buf.colorMode(HSB, 360, 100, 100, 100);
  S.buf.noStroke();
  S.buf.background(gH, gS, gB);
  S.key = key; S.bw = BW; S.bh = BH;
}
const g = S.buf, bw = S.bw, bh = S.bh, bu = Math.min(bw,bh);

// --- dramaturgy + audio (clk baseline carries motion; audio only adds on top) ---
const sect = K.section||0, intn = clp((K.intensity!=null?K.intensity:.6),0,1);
const hueShift = sect*15;
const aud = A.rms*0.5 + A.bass*0.4;

// --- evolving perlin flow field: drifts, scrolls & rotates on K.t forever ---
const sp = (2.3 / Math.max(bw,bh)) / clp(P.scale,0.35,3);
const zt = K.t*(0.05 + P.speed*0.06) + sd*0.37;
const scx = K.t*(bu*0.010 + P.speed*bu*0.015);
const scy = K.t*(bu*0.006);
const rotG = K.t*(0.03 + P.speed*0.035);
const coil = 1.0 + P.warp*3.5 + intn*1.0 + A.lowmid*0.8;
function fang(px,py){
  let n = noise((px+scx)*sp, (py+scy)*sp, zt);
  if (P.warp>0.02) n += (noise((px+scx)*sp*2.3+11.2, (py+scy)*sp*2.3+4.7, zt*1.4)-0.5)*P.warp*0.55;
  return n*TAU*coil + rotG;
}

// --- fade previous fabric toward ground (partial → trails weave & linger) ---
g.push();
g.noStroke();
g.blendMode(BLEND);
g.fill(gH, gS, gB, fadeA*(1 - intn*0.28));
g.rect(0,0,bw,bh);
g.blendMode(addMode ? ADD : BLEND);

// --- trace & braid ribbons through the field, re-integrated every frame ---
const NR = Math.round(7 + P.density*30);
const L = 36;
const stepPx = bu*0.011*(0.55 + P.speed*0.9);
const baseW = bu*0.012*(0.45 + clp(P.scale,0.35,3)*0.7)*wMul;
const briBoost = intn*8 + aud*26;
const alBoost = 1 + K.swell*0.3 + A.rms*0.6;
let bud = 1500;

for (let r=0; r<NR && bud>0; r++){
  const h0 = hsh(r*2+1), h1 = hsh(r*2+2), h2 = hsh(r*2+3);
  let x = (P.x + (h0-0.5)*1.05 + 0.05*Math.sin(K.t*0.12 + r))*bw;
  let y = (P.y + (h1-0.5)*1.05 + 0.05*Math.cos(K.t*0.10 + r*1.3))*bh;
  let plx=0,ply=0,prx=0,pry=0;
  for (let k=0; k<=L && bud>0; k++){
    const t = k/L;
    const a = fang(x,y) + P.braid*Math.sin(k*0.45 + K.t*1.3 + r*2.0)*0.6;
    const w = baseW*(0.30 + Math.sin(Math.PI*t)*0.85);
    const nx = -Math.sin(a), ny = Math.cos(a);
    const lx = x+nx*w, ly = y+ny*w, rx = x-nx*w, ry = y-ny*w;
    if (k>0){
      const edge = 0.30 + Math.sin(Math.PI*t)*0.70;
      let hue, sat, bri, al;
      if (style==='aurora'){
        hue = (130 + (0.5+0.5*Math.sin(a*1.6 + K.t*0.3 + r))*150 + hueShift)%360;
        sat = 72; bri = 40 + Math.sin(Math.PI*t)*30 + briBoost; al = edge*(4 + P.energy*13)*alBoost;
      } else if (style==='copper'){
        hue = (20 + (h2-0.5)*14 + 360)%360;
        sat = 88; bri = 42 + Math.sin(k*0.5 - K.t*2.5 + r)*34 + briBoost; al = edge*(8 + P.energy*20)*alBoost;
      } else if (style==='watercolor'){
        hue = (P.hue + t*80 + (h0-0.5)*46 + hueShift + 360)%360;
        sat = 34; bri = 46 + Math.sin(Math.PI*t)*14; al = edge*(5 + P.energy*9)*alBoost;
      } else if (style==='blueprint'){
        hue = (206 + (h2-0.5)*12 + 360)%360;
        sat = 12; bri = 82 + briBoost*0.4; al = edge*(8 + P.energy*17)*alBoost;
      } else { // silk — sunset spectrum along ribbon length
        hue = (P.hue + t*115 + (h0-0.5)*24 + hueShift + 360)%360;
        sat = 80; bri = 52 + Math.sin(Math.PI*t)*36 + briBoost; al = edge*(6 + P.energy*20)*alBoost;
      }
      g.fill(hue, sat, clp(bri,0,100), clp(al,0,45));
      g.quad(plx,ply, lx,ly, rx,ry, prx,pry);
      bud--;
    }
    plx=lx; ply=ly; prx=rx; pry=ry;
    x += Math.cos(a)*stepPx; y += Math.sin(a)*stepPx;
  }
}
g.blendMode(BLEND);
g.pop();

push();
if (P.alpha < 100) tint(0,0,100, P.alpha);
image(g, 0, 0, width, height);
pop();
